export const TESTIMONIALS = [
  {
    quote:
      "I wear the Vow Band every day and forget it's there — which is exactly what I wanted from a wedding ring. It's already got a story of its own after a year.",
    name: "Priya Nair",
    role: "Bengaluru",
  },
  {
    quote:
      "The Riverstone Pendant arrived with a little card telling me which riverbed the stone came from. Small thing, but it changed how I think about wearing it.",
    name: "Daniel Ortiz",
    role: "Austin, TX",
  },
  {
    quote:
      "Ordered the Ash Hoops not expecting much from a website — the weight and finish feel like something from my grandmother's box, not a new piece.",
    name: "Wren Sato",
    role: "Portland, OR",
  },
];
